CREATE SEQUENCE prepayments_id_seq AS BIGINT;
CREATE TABLE prepayments (
  id NUMERIC(20,0) DEFAULT nextval('prepayments_id_seq') CHECK (id BETWEEN 0 AND 18446744073709551615) NOT NULL ,
  user_id NUMERIC(20,0) CHECK (user_id BETWEEN 0 AND 18446744073709551615) NOT NULL,
  quote_id NUMERIC(20,0) CHECK (quote_id BETWEEN 0 AND 18446744073709551615) NOT NULL,
  idempotency_key_hash BYTEA CHECK (octet_length(idempotency_key_hash) = 32) NOT NULL,
  out_trade_no BYTEA CHECK (octet_length(out_trade_no) <= 64) NOT NULL,
  expected_appid BYTEA CHECK (octet_length(expected_appid) <= 64) NOT NULL,
  expected_mchid BYTEA CHECK (octet_length(expected_mchid) <= 64) NOT NULL,
  expected_amount_cents NUMERIC(20,0) CHECK (expected_amount_cents BETWEEN 0 AND 18446744073709551615) NOT NULL,
  currency CHAR(3) NOT NULL,
  provider_create_request_json JSONB NOT NULL,
  provider_create_request_digest BYTEA CHECK (octet_length(provider_create_request_digest) = 32) NOT NULL,
  effective_deadline TIMESTAMPTZ(6) NOT NULL,
  provider_state TEXT CHECK (provider_state IN ('READY','CREATE_CLAIMED','CREATE_UNKNOWN','PAYMENT_REQUESTED','NOT_PAID','PAID','CLOSED')) NOT NULL,
  create_attempted_at TIMESTAMPTZ(6) NULL,
  wx_request_payment_json JSONB NULL,
  provider_prepay_id BYTEA CHECK (octet_length(provider_prepay_id) <= 128) NULL,
  last_queried_at TIMESTAMPTZ(6) NULL,
  materialization_state TEXT CHECK (materialization_state IN ('AWAITING_PAYMENT','READY','APPLIED','PENDING_MANUAL','REFUNDED_WITHOUT_ORDER')) NOT NULL,
  pending_reason_code VARCHAR(64) NULL,
  materialized_at TIMESTAMPTZ(6) NULL,
  lease_kind TEXT CHECK (lease_kind IN ('CREATE','QUERY')) NULL,
  lease_owner BYTEA CHECK (octet_length(lease_owner) = 16) NULL,
  lease_expires_at TIMESTAMPTZ(6) NULL,
  record_version NUMERIC(20,0) CHECK (record_version BETWEEN 0 AND 18446744073709551615) NOT NULL DEFAULT 1,
  next_reconcile_at TIMESTAMPTZ(6) NULL,
  created_at TIMESTAMPTZ(6) NOT NULL,
  updated_at TIMESTAMPTZ(6) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uq_prepayments_quote UNIQUE (quote_id),
  CONSTRAINT uq_prepayments_out_trade_no UNIQUE (out_trade_no),
  CONSTRAINT uq_prepayments_user_idempotency UNIQUE (user_id,idempotency_key_hash),
  CONSTRAINT fk_prepayments_user FOREIGN KEY (user_id) REFERENCES miniprogram_users (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_prepayments_quote FOREIGN KEY (quote_id) REFERENCES quotes (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_prepayments_immutable CHECK (OCTET_LENGTH(out_trade_no) BETWEEN 1 AND 64 AND OCTET_LENGTH(expected_appid) BETWEEN 1 AND 64 AND OCTET_LENGTH(expected_mchid) BETWEEN 1 AND 64 AND expected_amount_cents>0 AND currency='CNY' AND jsonb_typeof(provider_create_request_json)='object' AND effective_deadline>created_at),
  CONSTRAINT chk_prepayments_lease_group CHECK ((lease_kind IS NULL AND lease_owner IS NULL AND lease_expires_at IS NULL) OR (lease_kind IS NOT NULL AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)),
  CONSTRAINT chk_prepayments_provider_state CHECK ((provider_state='READY' AND create_attempted_at IS NULL AND provider_prepay_id IS NULL AND wx_request_payment_json IS NULL AND lease_kind IS NULL) OR (provider_state='CREATE_CLAIMED' AND create_attempted_at IS NOT NULL AND provider_prepay_id IS NULL AND wx_request_payment_json IS NULL AND lease_kind='CREATE') OR (provider_state='CREATE_UNKNOWN' AND create_attempted_at IS NOT NULL AND provider_prepay_id IS NULL AND wx_request_payment_json IS NULL AND (lease_kind IS NULL OR lease_kind='QUERY')) OR (provider_state='PAYMENT_REQUESTED' AND create_attempted_at IS NOT NULL AND provider_prepay_id IS NOT NULL AND wx_request_payment_json IS NOT NULL AND (lease_kind IS NULL OR lease_kind='QUERY')) OR (provider_state IN ('NOT_PAID','PAID','CLOSED') AND create_attempted_at IS NOT NULL AND ((provider_prepay_id IS NULL AND wx_request_payment_json IS NULL) OR (provider_prepay_id IS NOT NULL AND wx_request_payment_json IS NOT NULL)) AND (lease_kind IS NULL OR lease_kind='QUERY'))),
  CONSTRAINT chk_prepayments_materialization CHECK ((materialization_state IN ('AWAITING_PAYMENT','READY') AND pending_reason_code IS NULL AND materialized_at IS NULL) OR (materialization_state IN ('APPLIED','REFUNDED_WITHOUT_ORDER') AND pending_reason_code IS NULL AND materialized_at IS NOT NULL) OR (materialization_state='PENDING_MANUAL' AND pending_reason_code IS NOT NULL AND CHAR_LENGTH(TRIM(pending_reason_code))>0 AND materialized_at IS NULL)),
  CONSTRAINT chk_prepayments_record_version CHECK (record_version>0)
);
CREATE INDEX idx_prepayments_next_reconcile ON prepayments (next_reconcile_at,id);
ALTER SEQUENCE prepayments_id_seq OWNED BY prepayments.id;
